import torch
import torch.nn as nn
import torch.nn.functional as F
import hashlib
from torch.utils.cpp_extension import load_inline

_STARK_EXTENSION = None

def _stark_strip_anchor_markers(source: str) -> str:
    cleaned_lines = []
    for line in source.splitlines():
        stripped = line.lstrip()
        if stripped.startswith('# <<<IMPROVE:') or stripped.startswith('# <<<END_IMPROVE>>>'):
            continue
        cleaned_lines.append(line)
    return '\n'.join(cleaned_lines)

def _stark_extension_name() -> str:
    digest = hashlib.sha1((_stark_strip_anchor_markers(CUDA_CPP_SRC) + _stark_strip_anchor_markers(CUDA_CU_SRC)).encode('utf-8')).hexdigest()[:12]
    return f'stark_cuda_l3_p21_{digest}'

def _stark_get_extension():
    global _STARK_EXTENSION
    if _STARK_EXTENSION is None:
        _STARK_EXTENSION = load_inline(
            name=_stark_extension_name(),
            cpp_sources=_stark_strip_anchor_markers(CUDA_CPP_SRC),
            cuda_sources=_stark_strip_anchor_markers(CUDA_CU_SRC),
            functions=None,
            extra_cflags=['-O3'],
            extra_cuda_cflags=['-O3', '--use_fast_math'],
            with_cuda=True,
            verbose=False,
        )
    return _STARK_EXTENSION

# <<<IMPROVE:user_helpers>>>
def _stark_fold_conv_bn_params(conv, bn):
    """
    Fold BatchNorm2d into the preceding Conv2d for inference.
    Returns (folded_weight, folded_bias) ready for F.conv2d.
    """
    with torch.no_grad():
        scale = bn.weight * torch.rsqrt(bn.running_var + bn.eps)
        # Reshape scale to [out_channels, 1, 1, 1] for broadcast over conv weight
        scale_w = scale.view(-1, 1, 1, 1)
        folded_weight = conv.weight * scale_w
        if conv.bias is None:
            folded_bias = bn.bias - bn.running_mean * scale
        else:
            folded_bias = (conv.bias - bn.running_mean) * scale + bn.bias
        return folded_weight, folded_bias
# <<<END_IMPROVE>>>

CUDA_CPP_SRC = r"""
# <<<IMPROVE:cuda_cpp>>>
#include <torch/extension.h>

torch::Tensor bn_relu6_inference_cuda(
    torch::Tensor x,
    torch::Tensor gamma,
    torch::Tensor beta,
    torch::Tensor running_mean,
    torch::Tensor running_var,
    double eps);

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("bn_relu6_inference_cuda", &bn_relu6_inference_cuda, "BN+ReLU6 inference (CUDA)");
}
# <<<END_IMPROVE>>>
"""

CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void bn_relu6_kernel(
    const float* __restrict__ x,
    const float* __restrict__ gamma,
    const float* __restrict__ beta,
    const float* __restrict__ running_mean,
    const float* __restrict__ running_var,
    float* __restrict__ out,
    float eps,
    int64_t N,
    int64_t C,
    int64_t HW
) {
    int64_t idx = blockIdx.x * blockDim.x + threadIdx.x;
    int64_t stride = blockDim.x * gridDim.x;

    for (int64_t i = idx; i < N * C * HW; i += stride) {
        int64_t c = (i / HW) % C;
        float val = x[i];
        float mean = running_mean[c];
        float var = running_var[c];
        float g = gamma[c];
        float b = beta[c];

        float normalized = (val - mean) * rsqrtf(var + eps);
        float affine = normalized * g + b;
        float clamped = fminf(fmaxf(affine, 0.0f), 6.0f);

        out[i] = clamped;
    }
}

torch::Tensor bn_relu6_inference_cuda(
    torch::Tensor x,
    torch::Tensor gamma,
    torch::Tensor beta,
    torch::Tensor running_mean,
    torch::Tensor running_var,
    double eps
) {
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(x.is_contiguous(), "x must be contiguous");
    TORCH_CHECK(x.scalar_type() == torch::kFloat32, "x must be float32");
    TORCH_CHECK(gamma.is_cuda() && gamma.is_contiguous(), "gamma must be CUDA contiguous");
    TORCH_CHECK(beta.is_cuda() && beta.is_contiguous(), "beta must be CUDA contiguous");
    TORCH_CHECK(running_mean.is_cuda() && running_mean.is_contiguous(), "running_mean must be CUDA contiguous");
    TORCH_CHECK(running_var.is_cuda() && running_var.is_contiguous(), "running_var must be CUDA contiguous");

    auto out = torch::empty_like(x);

    int64_t N = x.size(0);
    int64_t C = x.size(1);
    int64_t H = x.size(2);
    int64_t W = x.size(3);
    int64_t HW = H * W;
    int64_t total = N * C * HW;

    const int threads = 256;
    const int blocks = (total + threads - 1) / threads;

    bn_relu6_kernel<<<blocks, threads>>>(
        x.data_ptr<float>(),
        gamma.data_ptr<float>(),
        beta.data_ptr<float>(),
        running_mean.data_ptr<float>(),
        running_var.data_ptr<float>(),
        out.data_ptr<float>(),
        static_cast<float>(eps),
        N, C, HW
    );

    return out;
}
# <<<END_IMPROVE>>>
"""

class ModelNew(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size, stride, expand_ratio):
        super().__init__()
        # <<<IMPROVE:init_body>>>
        self.use_residual = (stride == 1 and in_channels == out_channels)
        hidden_dim = in_channels * expand_ratio
        if expand_ratio != 1:
            self.expand_conv = nn.Conv2d(in_channels, hidden_dim, kernel_size=1, stride=1, padding=0, bias=False)
            self.expand_bn = nn.BatchNorm2d(hidden_dim)
            self.expand_act = nn.ReLU6(inplace=True)
        self.depthwise_conv = nn.Conv2d(hidden_dim, hidden_dim, kernel_size=kernel_size, stride=stride, padding=(kernel_size - 1) // 2, groups=hidden_dim, bias=False)
        self.depthwise_bn = nn.BatchNorm2d(hidden_dim)
        self.depthwise_act = nn.ReLU6(inplace=True)
        self.project_conv = nn.Conv2d(hidden_dim, out_channels, kernel_size=1, stride=1, padding=0, bias=False)
        self.project_bn = nn.BatchNorm2d(out_channels)
        # <<<END_IMPROVE>>>

    def forward(self, x):
        # <<<IMPROVE:forward_stmt_1>>>
        # Baseline fallback keeps the official PyTorch forward path.
        # After implementing CUDA_CPP_SRC / CUDA_CU_SRC, call _stark_get_extension().your_entrypoint(...).
        """
                Forward pass of the MBConv block.

                :param x: The input tensor, shape (batch_size, in_channels, H, W)
                :return: The output tensor, shape (batch_size, out_channels, H', W')
                """
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_2>>>
        identity = x
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_3>>>
        if hasattr(self, 'expand_conv'):
            if (not self.training) and x.is_cuda:
                conv_out = self.expand_conv(x)
                x = _stark_get_extension().bn_relu6_inference_cuda(
                    conv_out.contiguous(),
                    self.expand_bn.weight.contiguous(),
                    self.expand_bn.bias.contiguous(),
                    self.expand_bn.running_mean.contiguous(),
                    self.expand_bn.running_var.contiguous(),
                    float(self.expand_bn.eps)
                )
            else:
                x = self.expand_act(self.expand_bn(self.expand_conv(x)))
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_4>>>
        if (not self.training) and x.is_cuda:
            weight, bias = _stark_fold_conv_bn_params(self.depthwise_conv, self.depthwise_bn)
            x = F.conv2d(x, weight, bias,
                         stride=self.depthwise_conv.stride,
                         padding=self.depthwise_conv.padding,
                         dilation=self.depthwise_conv.dilation,
                         groups=self.depthwise_conv.groups)
            x = self.depthwise_act(x)
        else:
            x = self.depthwise_act(self.depthwise_bn(self.depthwise_conv(x)))
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_5>>>
        if (not self.training) and x.is_cuda:
            weight, bias = _stark_fold_conv_bn_params(self.project_conv, self.project_bn)
            x = F.conv2d(x, weight, bias,
                         stride=self.project_conv.stride,
                         padding=self.project_conv.padding,
                         dilation=self.project_conv.dilation,
                         groups=self.project_conv.groups)
        else:
            x = self.project_bn(self.project_conv(x))
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_6>>>
        if self.use_residual:
                    x += identity
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_7>>>
        return x
        # <<<END_IMPROVE>>>

