import hashlib
from torch.utils.cpp_extension import load_inline

_STARK_EXTENSION = None

def _stark_strip_anchor_markers(source: str) -> str:
    cleaned_lines = []
    for line in source.splitlines():
        stripped = line.lstrip()
        if stripped.startswith('# <<<IMPROVE:') or stripped.startswith('# <<<END_IMPROVE>>>'):
            continue
        cleaned_lines.append(line)
    return '\n'.join(cleaned_lines)

def _stark_extension_name() -> str:
    digest = hashlib.sha1((_stark_strip_anchor_markers(CUDA_CPP_SRC) + _stark_strip_anchor_markers(CUDA_CU_SRC)).encode('utf-8')).hexdigest()[:12]
    return f'stark_cuda_l3_p21_{digest}'

def _stark_get_extension():
    global _STARK_EXTENSION
    if _STARK_EXTENSION is None:
        _STARK_EXTENSION = load_inline(
            name=_stark_extension_name(),
            cpp_sources=_stark_strip_anchor_markers(CUDA_CPP_SRC),
            cuda_sources=_stark_strip_anchor_markers(CUDA_CU_SRC),
            functions=None,
            extra_cflags=['-O3'],
            extra_cuda_cflags=['-O3', '--use_fast_math'],
            with_cuda=True,
            verbose=False,
        )
    return _STARK_EXTENSION

# <<<IMPROVE:user_helpers>>>
def _stark_fold_conv_bn_params(conv, bn):
    """
    Fold BatchNorm2d into the preceding Conv2d for inference.
    Returns (folded_weight, folded_bias) ready for F.conv2d.
    """
    with torch.no_grad():
        scale = bn.weight * torch.rsqrt(bn.running_var + bn.eps)
        scale_w = scale.view(-1, 1, 1, 1)
        folded_weight = conv.weight * scale_w
        if conv.bias is None:
            folded_bias = bn.bias - bn.running_mean * scale
        else:
            folded_bias = (conv.bias - bn.running_mean) * scale + bn.bias
        return folded_weight, folded_bias

def _stark_get_cached_folded(module, cache_name, conv, bn):
    """
    Return cached (folded_weight, folded_bias) for the given conv+bn pair,
    recomputing if the cache is stale (None, wrong device, or wrong dtype).
    """
    cached = getattr(module, cache_name, None)
    target_device = conv.weight.device
    target_dtype = conv.weight.dtype
    if (cached is not None
            and cached[0].device == target_device
            and cached[0].dtype == target_dtype):
        return cached
    w, b = _stark_fold_conv_bn_params(conv, bn)
    setattr(module, cache_name, (w, b))
    return w, b
