    TORCH_CHECK(weight.dim() == 4, "depthwise_conv2d_relu6: weight must be 4D [C,1,K,K]");
    TORCH_CHECK(weight.size(1) == 1, "depthwise_conv2d_relu6: weight dim 1 must be 1 (depthwise)");
    TORCH_CHECK(weight.size(2) == weight.size(3), "depthwise_conv2d_relu6: weight must be square");

    int N = (int)x.size(0), C = (int)x.size(1);
    int H = (int)x.size(2), W = (int)x.size(3);
    int K = (int)weight.size(2);
    TORCH_CHECK(bias.size(0) == C, "depthwise_conv2d_relu6: bias size must match channels");

    int H_out = (H + 2 * pad_h - K) / stride_h + 1;
    int W_out = (W + 2 * pad_w - K) / stride_w + 1;

    auto output = torch::empty({N, C, H_out, W_out}, x.options());

    int total = N * C * H_out * W_out;
    if (total == 0) return output;

    const int block = 256;
    int grid = (total + block - 1) / block;

